@startuml

class Person {
  + personId : int
  + phoneNumber : string
  + keywords : string[]
}

class ResearchInstitution {
  + institutionCode : int
}

class ScientificArticle {
  + doi : string
  + title : string
}

abstract class PeerReviewedPaper {
  + citationCount : int
}

class TechnicalReport {}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
}

class AuthorRole {
  + position : int
}

class ReviewerRole {}

class Subscription {
}

Person "1" -- "1" ResearchInstitution : worksFor
Person "1" -- "0..*" AuthorRole : authoredBy
AuthorRole "1" -- "1" ScientificArticle : forArticle
Person "1" -- "0..*" ReviewerRole : reviewedBy
ReviewerRole "1" -- "1" PeerReviewedPaper : reviewedPaper

ScientificArticle --|> PeerReviewedPaper
ScientificArticle --|> TechnicalReport

PeerReviewedPaper "1" -- "1..*" Journal : publishedIn
TechnicalReport "1" -- "1" ResearchInstitution : publishedBy

Publisher "1" -- "1..*" Journal : publishes
ResearchInstitution "1" -- "0..*" Subscription : has
Subscription "1" -- "1" Journal : forJournal

@enduml

